  color: var(--color-text-primary);
  font-family: var(--font-body);
  font-size: var(--font-size-md);
  line-height: 1.5;
  background-image:
    linear-gradient(rgba(0, 212, 255, 0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(0, 212, 255, 0.03) 1px, transparent 1px);
  background-size: 40px 40px;
}

/* ============================================================
   PASO 3 — LAYOUT PRINCIPAL (#app)
   ============================================================ */

#app {
  display: grid;
  grid-template-rows: auto 1fr;
  grid-template-columns: 1fr;
  min-height: 100%;
  max-width: 1600px;
  margin: 0 auto;
  padding: var(--space-md);
  gap: var(--space-lg);
}

/* ============================================================
   PASO 4 — HEADER
   ============================================================ */

#header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-md) var(--space-lg);
  background-color: var(--color-bg-panel);
  border: 1px solid var(--color-border-idle);
  border-radius: var(--border-radius-panel);
  border-top: 2px solid var(--color-accent-cyan);
  box-shadow: var(--glow-cyan), inset 0 1px 0 rgba(0, 212, 255, 0.1);
  position: relative;
  overflow: hidden;
}

#header::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(
    135deg,
    rgba(0, 212, 255, 0.04) 0%,
    transparent 50%,
    rgba(255, 0, 110, 0.02) 100%
  );
  pointer-events: none;
}

#header-brand {
  display: flex;
  align-items: center;
  gap: var(--space-md);
}

#header-logo-icon {
  width: 48px;
  height: 48px;
  border: 2px solid var(--color-accent-cyan);
  border-radius: var(--border-radius-panel);
  background: linear-gradient(
    135deg,
    rgba(0, 212, 255, 0.15) 0%,
    rgba(0, 212, 255, 0.05) 100%
  );
  box-shadow: var(--glow-cyan);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.4rem;
  flex-shrink: 0;
}

#header-titles {
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
}

#header-title {
  font-family: var(--font-display);
  font-size: var(--font-size-xl);
  font-weight: 700;
  color: var(--color-accent-cyan);
  text-shadow: var(--glow-cyan);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

#header-subtitle {
  font-family: var(--font-body);
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

#header-status {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: var(--space-sm) var(--space-md);
  border: 1px solid var(--color-border-idle);
  border-radius: var(--border-radius-btn);
  background-color: rgba(0, 0, 0, 0.3);
}

#status-indicator {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.status-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: var(--color-text-disabled);
  transition: background-color var(--transition-med), box-shadow var(--transition-med);
  flex-shrink: 0;
}

.status-dot.status-active {
  background-color: var(--color-accent-green);
  box-shadow: var(--glow-green);
  animation: pulse-dot 2s ease-in-out infinite;
}

#status-label {
  font-family: var(--font-body);
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

@keyframes pulse-dot {
  0%, 100% { opacity: 1; }
  50%       { opacity: 0.5; }
}

/* ============================================================
   PASO 5 — LAYOUT DEL CUERPO PRINCIPAL (dos columnas)
   ============================================================ */

#app > main {
  display: grid;
  grid-template-columns: 340px 1fr;
  gap: var(--space-lg);
  align-items: start;
}

/* ============================================================
   PASO 6 — PANEL DE CONTROL (columna izquierda)
   ============================================================ */

#control-panel {
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
  background-color: var(--color-bg-panel);
  border: 1px solid var(--color-border-idle);
  border-radius: var(--border-radius-panel);
  padding: var(--space-lg);
  position: sticky;
  top: var(--space-md);
}

#control-panel-title {
  font-family: var(--font-display);
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  letter-spacing: 0.15em;
  text-transform: uppercase;
  padding-bottom: var(--space-md);
  border-bottom: 1px solid var(--color-border-idle);
}

/* ============================================================
   PASO 7 — GRID DE MÓDULOS
   ============================================================ */

#modules-grid {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

/* ============================================================
   PASO 8 — MODULE CARD
   ============================================================ */

.module-card {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  padding: var(--space-md);
  background-color: var(--color-bg-panel);
  border: 1px solid var(--color-border-idle);
  border-radius: var(--border-radius-panel);
  cursor: pointer;
  transition:
    background-color var(--transition-fast),
    border-color var(--transition-fast),
    box-shadow var(--transition-fast);
  position: relative;
  overflow: hidden;
}

.module-card::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 3px;
  background-color: var(--color-border-idle);
  transition: background-color var(--transition-fast), box-shadow var(--transition-fast);
}

.module-card:hover {
  background-color: var(--color-bg-panel-hover);
  border-color: var(--color-border-active);
}

.module-card.module-card--active {
  background-color: var(--color-bg-panel-hover);
  border-color: var(--color-border-active);
  box-shadow: var(--glow-cyan);
}

.module-card.module-card--active::before {
  background-color: var(--color-accent-cyan);
  box-shadow: var(--glow-cyan);
}

.module-icon {
  width: 36px;
  height: 36px;
  border-radius: var(--border-radius-btn);
  background: linear-gradient(
    135deg,
    rgba(0, 212, 255, 0.12) 0%,
    rgba(0, 212, 255, 0.04) 100%
  );
  border: 1px solid var(--color-border-idle);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--font-size-lg);
  flex-shrink: 0;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.module-card.module-card--active .module-icon {
  border-color: var(--color-accent-cyan);
  box-shadow: var(--glow-cyan);
}

.module-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.module-name {
  font-family: var(--font-body);
  font-size: var(--font-size-md);
  color: var(--color-text-primary);
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  transition: color var(--transition-fast);
}

.module-card.module-card--active .module-name {
  color: var(--color-accent-cyan);
}

.module-desc {
  font-family: var(--font-body);
  font-size: var(--font-size-xs);
  color: var(--color-text-secondary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ============================================================
   PASO 9 — TOGGLE SWITCH
   ============================================================ */

.module-toggle {
  position: relative;
  flex-shrink: 0;
}

.toggle-switch {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
  pointer-events: none;
}

.toggle-slider {
  display: block;
  width: 40px;
  height: 22px;
  background-color: var(--color-bg-deep);
  border: 1px solid var(--color-border-idle);
  border-radius: 11px;
  cursor: pointer;
  position: relative;
  transition:
    background-color var(--transition-fast),
    border-color var(--transition-fast),
    box-shadow var(--transition-fast);
}

.toggle-slider::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background-color: var(--color-text-disabled);
  transition:
    transform var(--transition-fast),
    background-color var(--transition-fast),
    box-shadow var(--transition-fast);
}

.toggle-switch:checked + .toggle-slider {
  background-color: rgba(0, 212, 255, 0.15);
  border-color: var(--color-accent-cyan);
  box-shadow: var(--glow-cyan);
}

.toggle-switch:checked + .toggle-slider::after {
  transform: translateX(18px);
  background-color: var(--color-accent-cyan);
  box-shadow: var(--glow-cyan);
}

/* ============================================================
   PASO 10 — BOTÓN OVERDRIVE
   ============================================================ */

#btn-overdrive {
  width: 100%;
  padding: var(--space-md) var(--space-lg);
  margin-top: var(--space-sm);
  font-family: var(--font-display);
  font-size: var(--font-size-sm);
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--color-accent-yellow);
  background: linear-gradient(
    135deg,
    rgba(255, 215, 0, 0.08) 0%,
    rgba(255, 215, 0, 0.03) 100%
  );
  border: 1px solid var(--color-accent-yellow);
  border-radius: var(--border-radius-btn);
  cursor: pointer;
  transition:
    background var(--transition-fast),
    box-shadow var(--transition-fast),
    color var(--transition-fast);
  position: relative;
  overflow: hidden;
}

#btn-overdrive::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    135deg,
    rgba(255, 215, 0, 0.15) 0%,
    transparent 100%
  );
  opacity: 0;
  transition: opacity var(--transition-fast);
}

#btn-overdrive:hover::before {
  opacity: 1;
}

#btn-overdrive:hover {
  box-shadow: var(--glow-yellow);
  color: var(--color-accent-yellow);
}

#btn-overdrive:active {
  transform: scale(0.98);
}

#btn-overdrive.overdrive--active {
  background: linear-gradient(
    135deg,
    rgba(255, 215, 0, 0.2) 0%,
    rgba(255, 215, 0, 0.08) 100%
  );
  box-shadow: var(--glow-yellow);
  animation: overdrive-pulse 1.5s ease-in-out infinite;
}

@keyframes overdrive-pulse {
  0%, 100% { box-shadow: var(--glow-yellow); }
  50%       { box-shadow: 0 0 20px #ffd700, 0 0 50px rgba(255, 215, 0, 0.6); }
}

/* ============================================================
   PASO 11 — COLUMNA DERECHA (KPIs + Viz + Log)
   ============================================================ */

#app > main > .dashboard-right {
  display: flex;
  flex-direction: column;
  gap: var(--space-lg);
}

/* ============================================================
   PASO 12 — KPI GRID
   ============================================================ */

#kpi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: var(--space-md);
}

.kpi-card {
  background-color: var(--color-bg-panel);
  border: 1px solid var(--color-border-idle);
  border-radius: var(--border-radius-panel);
  padding: var(--space-lg);
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
  position: relative;
  overflow: hidden;
  transition:
    border-color var(--transition-med),
    box-shadow var(--transition-med);
}

.kpi-card::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(
    90deg,
    transparent,
    var(--color-accent-cyan),
    transparent
  );
  opacity: 0.5;
}

.kpi-card:hover {
  border-color: var(--color-border-active);
  box-shadow: var(--glow-cyan);
}

.kpi-label {
  font-family: var(--font-body);
  font-size: var(--font-size-xs);
  color: var(--color-text-secondary);
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.kpi-value {
  font-family: var(--font-display);
  font-size: var(--font-size-kpi);
  font-weight: 700;
  color: var(--color-accent-cyan);
  text-shadow: var(--glow-cyan);
  line-height: 1;
  letter-spacing: 0.04em;
  transition: color var(--transition-med), text-shadow var(--transition-med);
}

.kpi-delta {
  font-family: var(--font-body);
  font-size: var(--font-size-sm);
  color: var(--color-accent-green);
  display: flex;
  align-items: center;
  gap: var(--space-xs);
}

.kpi-delta--negative {
  color: var(--color-accent-magenta);
}

/* KPI cards con acento de color específico */
#kpi-card-roi .kpi-value {
  color: var(--color-accent-cyan);
  text-shadow: var(--glow-cyan);
}

#kpi-card-hours .kpi-value {
  color: var(--color-accent-green);
  text-shadow: var(--glow-green);
}

/* ============================================================
   PASO 13 — VIZ PANEL (Canvas + Charts)
   ============================================================ */

.viz-panel {
  background-color: var(--color-bg-panel);
  border: 1px solid var(--color-border-idle);
  border-radius: var(--border-radius-panel);
  padding: var(--space-lg);
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
  position: relative;
  overflow: hidden;
}

.viz-panel::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent,
    var(--color-accent-cyan),
    transparent
  );
}

.viz-title {
  font-family: var(--font-display);
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  letter-spacing: 0.15em;
  text-transform: uppercase;
  padding-bottom: var(--space-sm);
  border-bottom: 1px solid var(--color-border-idle);
}

/* Canvas de partículas */
#particle-canvas {
  display: block;
  width: 100%;
  border-radius: var(--border-radius-btn);
  background: linear-gradient(
    180deg,
    rgba(0, 212, 255, 0.02) 0%,
    rgba(5, 10, 15, 0.8) 100%
  );
}

/* ============================================================
   PASO 14 — CHART CONTAINER Y BARRAS
   ============================================================ */

.chart-container {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
  padding: var(--space-sm) 0;
}

.bar-group {
  display: grid;
  grid-template-columns: 100px 1fr 60px;
  align-items: center;
  gap: var(--space-sm);
}

.bar-label {
  font-family: var(--font-body);
  font-size: var(--font-size-xs);
  color: var(--color-text-secondary);
  text-align: right;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  letter-spacing: 0.06em;
}

.bar-track {
  height: 12px;
  background-color: rgba(26, 58, 92, 0.4);
  border-radius: 2px;
  overflow: hidden;
  position: relative;
}

.bar-fill {
  height: 100%;
  border-radius: 2px;
  background: linear-gradient(
    90deg,
    var(--color-accent-cyan),
    rgba(0, 212, 255, 0.6)
  );
  box-shadow: var(--glow-cyan);
  transition: width var(--transition-med), background var(--transition-med), box-shadow var(--transition-med);
  width: 0%;
}

.bar-fill--green {
  background: linear-gradient(
    90deg,
    var(--color-accent-green),
    rgba(0, 255, 136, 0.6)
  );
  box-shadow: var(--glow-green);
}

.bar-fill--magenta {
  background: linear-gradient(
    90deg,
    var(--color-accent-magenta),
    rgba(255, 0, 110, 0.6)
  );
  box-shadow: var(--glow-magenta);
}

.bar-fill--yellow {
  background: linear-gradient(
    90deg,
    var(--color-accent-yellow),
    rgba(255, 215, 0, 0.6)
  );
  box-shadow: var(--glow-yellow);
}

.bar-value {
  font-family: var(--font-body);
  font-size: var(--font-size-xs);
  color: var(--color-text-primary);
  text-align: left;
}

/* ============================================================
   PASO 15 — ACTIVITY LOG
   ============================================================ */

#activity-log-panel {
  background-color: var(--color-bg-panel);
  border: 1px solid var(--color-border-idle);
  border-radius: var(--border-radius-panel);
  padding: var(--space-lg);
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

#activity-log-panel .viz-title {
  flex-shrink: 0;
}

#activity-log {
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
  max-height: 220px;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--color-border-idle) transparent;
}

#activity-log::-webkit-scrollbar {
  width: 4px;
}

#activity-log::-webkit-scrollbar-track {
  background: transparent;
}

#activity-log::-webkit-scrollbar-thumb {
  background-color: var(--color-border-idle);
  border-radius: 2px;
}

.log-entry {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: var(--space-sm);
  align-items: baseline;
  padding: var(--space-xs) var(--space-sm);
  border-radius: var(--border-radius-btn);
  font-family: var(--font-body);
  font-size: var(--font-size-xs);
  line-height: 1.4;
  border-left: 2px solid transparent;
  transition: background-color var(--transition-fast);
  animation: log-slide-in var(--transition-med) ease-out;
}

.log-entry:hover {
  background-color: rgba(0, 212, 255, 0.04);
}

@keyframes log-slide-in {
  from {
    opacity: 0;
    transform: translateX(-8px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.log-entry-system {
  border-left-color: var(--color-text-disabled);
  color: var(--color-text-disabled);
}

.log-entry--info {
  border-left-color: var(--color-accent-cyan);
  color: var(--color-text-secondary);
}

.log-entry--success {
  border-left-color: var(--color-accent-green);
  color: var(--color-accent-green);
}

.log-entry--warning {
  border-left-color: var(--color-accent-yellow);
  color: var(--color-accent-yellow);
}

.log-entry--error {
  border-left-color: var(--color-accent-magenta);
  color: var(--color-accent-magenta);
}

.log-entry--overdrive {
  border-left-color: var(--color-accent-yellow);
  color: var(--color-accent-yellow);
  background-color: rgba(255, 215, 0, 0.05);
  text-shadow: 0 0 6px rgba(255, 215, 0, 0.4);
}

.log-timestamp {
  color: var(--color-text-disabled);
  font-size: var(--font-size-xs);
  white-space: nowrap;
  flex-shrink: 0;
}

.log-message {
  word-break: break-word;
}

/* ============================================================
   PASO 16 — ESTADOS GLOBALES DE MÓDULOS (por ID)
   ============================================================ */

#module-card-jira.module-card--active,
#module-card-confluence.module-card--active,
#module-card-bitbucket.module-card--active,
#module-card-compass.module-card--active,
#module-card-rovo.module-card--active {
  border-color: var(--color-border-active);
  box-shadow: var(--glow-cyan);
}

/* ============================================================
   PASO 17 — ESTADO OVERDRIVE GLOBAL
   ============================================================ */

body.overdrive-active #header {
  border-top-color: var(--color-accent-yellow);
  box-shadow: var(--glow-yellow), inset 0 1px 0 rgba(255, 215, 0, 0.1);
}

body.overdrive-active #header-title {
  color: var(--color-accent-yellow);
  text-shadow: var(--glow-yellow);
}

body.overdrive-active .kpi-value {
  color: var(--color-accent-yellow);
  text-shadow: var(--glow-yellow);
}

body.overdrive-active .status-dot.status-active {
  background-color: var(--color-accent-yellow);
  box-shadow: var(--glow-yellow);
}

/* ============================================================
   PASO 18 — RESPONSIVE
   ============================================================ */

@media (max-width: 1024px) {
  #app > main {
    grid-template-columns: 1fr;
  }

  #control-panel {
    position: static;
  }

  #modules-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  }
}

@media (max-width: 640px) {
  #app {
    padding: var(--space-sm);
    gap: var(--space-md);
  }

  #header {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--space-md);
  }

  #header-title {
    font-size: var(--font-size-lg);
  }

  #kpi-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .kpi-value {
    font-size: var(--font-size-xl);
  }

  .bar-group {
    grid-template-columns: 70px 1fr 50px;
  }

  #modules-grid {
    grid-template-columns: 1fr;
  }
}
